import { createRequire } from 'node:module'
import { readFileSync, mkdirSync } from 'node:fs'
import { join } from 'node:path'

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const captures = require('/home/runner/work/_temp/omgithub-runtime/scripts/wip-screenshots.cjs')
captures.instrument({ chromium })

const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
if (!process.env.DISPLAY) process.env.DISPLAY = ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()

const out = '/tmp/opencode/pulse-shots'
mkdirSync(out, { recursive: true })

const browser = await chromium.launch(config.browser.launchOptions)
const page = await browser.newPage({ viewport: { width: 1280, height: 900 } })
const failures = []
page.on('pageerror', error => failures.push('pageerror: ' + error.message))
page.on('console', message => { if (message.type() === 'error') failures.push('console: ' + message.text()) })
page.on('response', response => { if (response.status() >= 400) failures.push(`HTTP ${response.status()} ${response.url()}`) })

await page.goto('http://127.0.0.1:3000/', { waitUntil: 'load' })
await page.locator('#core').waitFor({ state: 'visible' })

const initial = {
  counter: await page.locator('#counter').textContent(),
  status: await page.locator('#status').textContent(),
  resultHidden: await page.locator('#result').isHidden(),
  best: await page.locator('#best').textContent()
}
await page.screenshot({ path: join(out, 'progress-idle.png') })

const box = await page.locator('#core').boundingBox()
for (let i = 0; i < 12; i++) {
  await page.mouse.click(box.x + box.width / 2, box.y + box.height / 2)
}

const running = {
  counter: await page.locator('#counter').textContent(),
  status: await page.locator('#status').textContent(),
  cps: await page.locator('#cps').textContent(),
  meterWidth: await page.locator('#meterFill').evaluate(el => el.style.width),
  live: await page.locator('#core').evaluate(el => el.classList.contains('live'))
}
await page.waitForTimeout(400)
await page.screenshot({ path: join(out, 'progress-running.png') })

await page.waitForFunction(() => !document.getElementById('result').hidden, null, { timeout: 20000 })
const finished = {
  counter: await page.locator('#counter').textContent(),
  status: await page.locator('#status').textContent(),
  resultScore: await page.locator('#resultScore').textContent(),
  resultRating: await page.locator('#resultRating').textContent(),
  resultBest: await page.locator('#resultBest').textContent(),
  best: await page.locator('#best').textContent()
}
await page.screenshot({ path: join(out, 'final-ended.png') })

await page.locator('#playAgain').click()
await page.waitForTimeout(150)
const restarted = {
  resultHidden: await page.locator('#result').isHidden(),
  status: await page.locator('#status').textContent(),
  counter: await page.locator('#counter').textContent()
}
await page.locator('#core').click()
await page.screenshot({ path: join(out, 'progress-restarted.png') })

const stored = await page.evaluate(() => localStorage.getItem('pulse.best.v1'))
const checks = {
  idleClean: initial.counter === '0' && initial.resultHidden && initial.best === '0',
  twelveClicks: running.counter === '12',
  clockRunning: /left$/.test(running.status) && running.meterWidth !== '100%' && running.live,
  cpsLive: /^[1-9]\d*\.\d CPS$/.test(running.cps),
  runEnded: finished.resultScore === '12' && finished.status === 'Run complete' && finished.best === '12',
  bestSaved: stored === '12' && finished.resultBest === 'Best · 12',
  playAgainStarts: restarted.resultHidden && /left$/.test(restarted.status) && restarted.counter === '0',
  restartCounts: (await page.locator('#counter').textContent()) === '1',
  noFailures: failures.length === 0
}

console.log(JSON.stringify({ initial, running, finished, restarted, stored, failures, checks }, null, 2))
await browser.close()
if (Object.values(checks).some(value => !value)) {
  console.error('VERIFICATION FAILED')
  process.exitCode = 1
} else {
  console.log('VERIFICATION PASSED')
}

import { createRequire } from 'node:module'
