import { join } from 'node:path'

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
if (!process.env.DISPLAY) process.env.DISPLAY = ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()

const browser = await chromium.launch(config.browser.launchOptions)
const page = await browser.newPage({ viewport: { width: 390, height: 844 } })
const errors = []
page.on('pageerror', error => errors.push(error.message))
await page.goto('http://127.0.0.1:3000/', { waitUntil: 'load' })

await page.keyboard.press('Space')
await page.waitForTimeout(150)
const firstKeyClick = await page.locator('#counter').textContent()
await page.keyboard.press('Enter')
await page.keyboard.press('Space')
await page.waitForTimeout(150)
const threeKeyClicks = await page.locator('#counter').textContent()

await page.waitForFunction(() => !document.getElementById('result').hidden, null, { timeout: 20000 })
const resultBox = await page.locator('#result').boundingBox()
const viewport = page.viewportSize()
const fits = resultBox.x >= 0 && resultBox.y >= 0 && resultBox.x + resultBox.width <= viewport.width && resultBox.y + resultBox.height <= viewport.height

await page.keyboard.press('Enter')
await page.waitForTimeout(150)
const restartedByKeyboard = await page.locator('#result').isHidden()
const focus = await page.evaluate(() => document.activeElement?.id)
await page.keyboard.press('Space')
const countAfterRestartKey = await page.locator('#counter').textContent()

console.log(JSON.stringify({ firstKeyClick, threeKeyClicks, fits, resultBox, viewport, restartedByKeyboard, focus, countAfterRestartKey, errors }, null, 2))
await browser.close()
if (firstKeyClick !== '1' || threeKeyClicks !== '3' || !fits || !restartedByKeyboard || focus !== 'core' || countAfterRestartKey !== '1' || errors.length) {
  console.error('KEYBOARD/MOBILE VERIFICATION FAILED')
  process.exitCode = 1
} else console.log('KEYBOARD/MOBILE VERIFICATION PASSED')

